    half_up = data.get("rounding", "floor") == "half_up"

    def rounded(numerator):
        return (numerator + 5000) // 10000 if half_up else numerator // 10000

    for _, event in selected.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = max(0, min(10000, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if discounted_tax else raw
        tax = rounded(base * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best = None

    def cyclic(edges):
        active, done = set(), set()

        def visit(name):
            if name in active:
                return True
            if name in done:
                return False
            active.add(name)
            for child in edges.get(name, ()):
                if visit(child):
                    return True
            active.remove(name)
            done.add(name)
            return False

        return any(visit(name) for name in edges if name not in done)

    def search(selected, constraints, edges):
        nonlocal best, best_vector
        unresolved = [name for name in constraints if name not in selected]
        if not unresolved:
            if cyclic(edges):
                return
            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, dict(selected)
            return

        name = max(unresolved)
        low, high = constraints[name]
        versions = sorted(
            (row["version"] for row in packages[name]
             if low <= row["version"] <= high
             and row["version"] not in blocked.get(name, [])
             and (name not in pins or row["version"] == pins[name])),
            reverse=True)
        for version in versions:
            row = next(row for row in packages[name] if row["version"] == version)
            next_selected = dict(selected)
            next_constraints = dict(constraints)
            next_edges = {key: list(value) for key, value in edges.items()}
            next_selected[name] = version
            dependencies = []
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                dependencies.append(child)
                lo, hi = dep["min"], dep["max"]
                if child in next_constraints:
                    old_lo, old_hi = next_constraints[child]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                next_constraints[child] = (lo, hi)
                if child in next_selected and not lo <= next_selected[child] <= hi:
                    valid = False
                    break
            if valid:
                next_edges[name] = dependencies
                search(next_selected, next_constraints, next_edges)

    roots = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    search({}, roots, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _component_07(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in combinations(jobs, k):
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(chosen, key=lambda row: (row["start"], row["end"], row["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in chosen)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                discounted = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((discounted, remaining - 1))
            for duration, coupons_left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, coupons_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, coupons_left))
    return {"arrival": None}


